import unittest
from candidate import change_base

class TestChangeBase(unittest.TestCase):
    def test_change_base_positive_number_base_2(self):
        self.assertEqual(change_base(8, 2), '1000')

    def test_change_base_positive_number_base_3(self):
        self.assertEqual(change_base(8, 3), '22')

    def test_change_base_positive_number_base_5(self):
        self.assertEqual(change_base(8, 5), '13')

    def test_change_base_zero(self):
        self.assertEqual(change_base(0, 2), '0')

    def test_change_base_base_1(self):
        with self.assertRaises(ZeroDivisionError):
            change_base(8, 1)

    def test_change_base_base_10(self):
        with self.assertRaises(ValueError):
            change_base(8, 10)

    def test_change_base_negative_number(self):
        with self.assertRaises(ValueError):
            change_base(-8, 2)

    def test_change_base_none_x(self):
        with self.assertRaises(TypeError):
            change_base(None, 2)

    def test_change_base_none_base(self):
        with self.assertRaises(TypeError):
            change_base(8, None)

    def test_change_base_non_integer_x(self):
        with self.assertRaises(TypeError):
            change_base(8.5, 2)

    def test_change_base_non_integer_base(self):
        with self.assertRaises(TypeError):
            change_base(8, 2.5)

if __name__ == '__main__':
    unittest.main()
